import React, { useEffect, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { ApiError, api, post, type Row } from './api';
import { deliveryPath, navigate, productPath, useRoute } from './router';
import { clearUxEvidence, readUxEvidence, recordUx } from './ux-evidence';
import { ProductWorkspace } from './product-workspace';
import './styles.css';

const paths: Record<string, [string, string, string]> = { undecided: ['Ask BMAD what next', 'Let BMAD inspect the intent and repository, explain its recommendation, then choose a path.', 'bmad-help'], direct: ['Direct attended Build', 'A small bounded change, with decisions made during implementation.', 'bmad-build'], 'spec-epic': ['Spec-backed epic', 'Create a concise spec and ordered stories, then deliver one story at a time.', 'bmad-spec → Build → review → retrospective'], project: ['Project-sized planning', 'Develop product, UX and architecture before epics, stories and delivery.', 'PRD / UX → architecture → epics → Build'], specialist: ['Research, review or course correction', 'Run a focused BMAD research or review workflow against existing work.', 'deep recon / review / correct course'] };
function deliverySummary(stream: Row) { const text = String(stream.intent || stream.summary || '').replace(/\s+/g, ' ').trim(); if (text.length <= 240) return text; const window = text.slice(0, 240), natural = Math.max(window.lastIndexOf('. '), window.lastIndexOf('! '), window.lastIndexOf('? ')); const end = natural >= 100 ? natural + 1 : window.lastIndexOf(' '); return `${window.slice(0, end > 0 ? end : 239).trim()}…`; }

function App() {
    const route = useRoute();
    const [system, setSystem] = useState<Row>({}), [resources, setResources] = useState<Row>({}), [scheduler, setScheduler] = useState<Row>({}), [attention, setAttention] = useState<Row>({ sessions: [], invalidArtifacts: [], reviewFeedback: [] });
    const [portfolio, setPortfolio] = useState<Row[]>([]), [projects, setProjects] = useState<Row[]>([]), [repos, setRepos] = useState<Row[]>([]), [streams, setStreams] = useState<Row[]>([]), [sessions, setSessions] = useState<Row[]>([]), [artifacts, setArtifacts] = useState<Row[]>([]), [operations, setOperations] = useState<Row[]>([]), [stories, setStories] = useState<Row[]>([]), [graph, setGraph] = useState<Row>({ nodes: [], links: [] }), [readiness, setReadiness] = useState<Row>({ ready: false, total: 0, unfinished: [] }), [lifecycle, setLifecycle] = useState<Row>();
    const [deliveryStates, setDeliveryStates] = useState<Record<string, Row>>({});
    const [selectedSession, setSelectedSession] = useState<Row>(), [selectedArtifact, setSelectedArtifact] = useState<Row>(), [error, setError] = useState<Row>(), [busy, setBusy] = useState('');
    const [initialLoaded, setInitialLoaded] = useState(false);
    const routeProjectSlug = route.name === 'product' || route.name === 'delivery' ? route.productSlug : '';
    const project = projects.find(x => x.slug === routeProjectSlug || x.id === routeProjectSlug);
    const stream = route.name === 'delivery' ? streams.find(x => x.projectId === project?.id && (x.slug === route.deliverySlug || x.id === route.deliverySlug)) : undefined;
    const base = async () => { const [s, m, q, p, r, w, a] = await Promise.all([api('/system/status'), api('/resources'), api('/scheduler'), api('/products'), api('/repositories'), api('/workstreams'), api('/attention')]); const states = await Promise.all((w as Row[]).map(async item => [item.id, await api(`/workstreams/${item.id}/lifecycle`).catch(() => undefined)])); setSystem(s); setResources(m); setScheduler(q); setPortfolio(p); setProjects((p as Row[]).map(x => x.product)); setRepos(r); setStreams(w); setAttention(a); setDeliveryStates(Object.fromEntries(states.filter(([, value]) => value))); setInitialLoaded(true) };
    const loadStream = async (id = stream?.id) => { if (!id) return; const [ss, aa, oo, st, gr, rr, lc] = await Promise.all([api(`/workflow-sessions?workstreamId=${id}`), api(`/artifacts?workstreamId=${id}`), api(`/workstreams/${id}/operations`), api(`/stories?workstreamId=${id}`), api(`/workstreams/${id}/artifact-graph`), api(`/workstreams/${id}/retrospective-readiness`), api(`/workstreams/${id}/lifecycle`)]); setSessions(ss); setArtifacts(aa); setOperations(oo); setStories(st); setGraph(gr); setReadiness(rr); setLifecycle(lc) };
    const asProblem = (value: unknown): Row => value instanceof ApiError ? { message: value.message, code: value.code, status: value.status } : { message: value instanceof Error ? value.message : String(value) };
    const refresh = async () => { try { await base(); await loadStream(); setError(undefined) } catch (e) { setError(asProblem(e)) } finally { setInitialLoaded(true) } };
    useEffect(() => { recordUx('route_visited', { path: location.pathname, query: location.search }) }, [location.pathname, location.search]);
    useEffect(() => { if (!busy) return; const abandoned = () => recordUx('action_abandoned', { label: busy, path: location.pathname }); addEventListener('pagehide', abandoned, { once: true }); return () => removeEventListener('pagehide', abandoned) }, [busy]);
    useEffect(() => { void refresh(); const timer = setInterval(() => void base().catch(() => { }), 15000); return () => clearInterval(timer) }, []);
    useEffect(() => { if (stream?.id) void loadStream(stream.id) }, [stream?.id]);
    useEffect(() => {
        if (route.name !== 'delivery') return;
        if (route.view === 'run' && route.reference) void api(`/workflow-sessions/${route.reference}`).then(setSelectedSession).catch(e => setError(asProblem(e))); else setSelectedSession(undefined);
        if (route.view !== 'artifact') setSelectedArtifact(undefined);
    }, [route.name, route.name === 'delivery' ? route.view : '', route.name === 'delivery' ? route.reference : '']);
    useEffect(() => { if (route.name === 'delivery' && route.view === 'artifact' && route.reference) setSelectedArtifact(artifacts.find(x => x.id === route.reference)); }, [artifacts, route]);
    useEffect(() => {
        if (route.name === 'product' && project && route.productSlug !== project.slug) navigate(productPath(project.slug), true);
        if (route.name === 'delivery' && project && stream && (route.productSlug !== project.slug || route.deliverySlug !== stream.slug)) navigate(deliveryPath(project.slug, stream.slug), true);
    }, [route, project?.id, stream?.id]);
    useEffect(() => { if (route.name === 'delivery') requestAnimationFrame(() => document.querySelector<HTMLElement>('.stage')?.focus({ preventScroll: true })) }, [route]);
    useEffect(() => { if (!selectedSession || !['RUNNING', 'QUEUED', 'RESOURCE_WAITING'].includes(selectedSession.status)) return; const source = new EventSource(`/workflow-sessions/${selectedSession.id}/events`); source.onmessage = () => { void loadStream(); void api(`/workflow-sessions/${selectedSession.id}`).then(setSelectedSession) }; return () => source.close() }, [selectedSession?.id, selectedSession?.status]);
    const act = async (label: string, fn: () => Promise<any>) => { const started = performance.now(); setBusy(label); setError(undefined); try { const result = await fn(); await refresh(); recordUx('action_completed', { label, durationMs: Math.round(performance.now() - started) }); return result } catch (e) { const problem = asProblem(e); recordUx('error_shown', { label, category: problem.code ?? 'client_error', status: problem.status }); if (problem.code === 'stale_or_ineligible_action') await refresh(); setError(problem) } finally { setBusy('') } };
    const submit = (handler: (data: Record<string, string>, form: HTMLFormElement) => Promise<any>) => (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = event.currentTarget, data = Object.fromEntries(new FormData(form)) as Record<string, string>; void act('Saving', () => handler(data, form)) };
    const openProject = (id: string) => { const item = projects.find(x => x.id === id); if (item) navigate(productPath(item.slug)) };
    const openStream = (id: string) => { const item = streams.find(x => x.id === id), owner = projects.find(x => x.id === item?.projectId); if (item && owner) navigate(deliveryPath(owner.slug, item.slug)) };
    const pendingDecisions = Object.values(deliveryStates).filter(x => x.currentStage?.state === 'awaiting-decision' && x.attention);
    const count = (attention.sessions?.length ?? 0) + (attention.invalidArtifacts?.length ?? 0) + (attention.reviewFeedback?.length ?? 0) + pendingDecisions.length;
    const crumbs: Array<Array<string | undefined>> = route.name === 'product' ? [['Home', '/'], ['Products', '/products'], [project?.name ?? route.productSlug, '']]
      : route.name === 'delivery' ? [['Home', '/'], ['Products', '/products'], [project?.name ?? route.productSlug, project ? productPath(project.slug) : ''], [stream?.title ?? route.deliverySlug, '']]
      : route.name === 'products' ? [['Home', '/'], ['Products', '']] : [['Home', '']];
    if (route.name === 'delivery' && route.view !== 'current') {
        const label = route.view === 'stage' ? route.reference : route.view === 'run' ? 'Conversation' : route.view === 'artifact' ? selectedArtifact?.path.split('/').at(-1) ?? 'Artifact' : 'Advanced actions';
        crumbs[crumbs.length - 1][1] = stream && project ? deliveryPath(project.slug, stream.slug) : '';
        crumbs.push([label, '']);
    }
    return <div className="appShell" aria-busy={Boolean(busy)}><a className="skipLink" href="#main-content">Skip to current workspace</a><header><button className="brand" onClick={() => navigate('/')}><b>MIC</b><span>Development control plane</span></button><nav><button onClick={() => navigate('/')}>Home</button><button onClick={() => navigate('/products')}>Products</button><a href="/docs" target="_blank" rel="noreferrer">API docs ↗</a></nav></header><main id="main-content"><Breadcrumbs items={crumbs} />{error && <Problem problem={error} retry={() => void refresh()} dismiss={() => setError(undefined)} />} {busy && <div className="notice busy" role="status" aria-live="polite">{busy}…</div>}
        {route.name === 'home' && <Home system={system} resources={resources} scheduler={scheduler} streams={streams} deliveryStates={deliveryStates} pendingDecisions={pendingDecisions} attention={attention} count={count} openStream={openStream} projects={() => navigate('/products')} />}
        {route.name === 'products' && <Products portfolio={portfolio} open={openProject} submit={submit} />}
        {route.name === 'product' && project && <ProductWorkspace product={project} section={route.section ?? 'overview'} reference={route.reference} repos={repos.filter(x => x.projectId === project.id)} streams={streams.filter(x => x.projectId === project.id)} deliveryStates={deliveryStates} openDelivery={openStream} submit={submit} act={act} />}
        {route.name === 'delivery' && stream && project && <Workstream stream={stream} product={project} route={route} lifecycle={lifecycle} sessions={sessions} artifacts={artifacts} graph={graph} readiness={readiness} operations={operations} stories={stories} selectedSession={selectedSession} selectedArtifact={selectedArtifact} selectSession={(x: Row) => navigate(`${deliveryPath(project.slug, stream.slug)}/runs/${x.id}`)} selectArtifact={(x: Row) => navigate(`${deliveryPath(project.slug, stream.slug)}/artifacts/${x.id}`)} submit={submit} act={act} load={loadStream} back={() => navigate(productPath(project.slug))} started={(x: Row) => navigate(`${deliveryPath(project.slug, stream.slug)}/runs/${x.id}`)} />}
        {route.name === 'settings' && <UxEvidencePanel />}
        {!initialLoaded && (route.name === 'product' || route.name === 'delivery') && <Panel title="Loading workspace"><p>Resolving the durable Product and Delivery route…</p></Panel>}
        {initialLoaded && ((route.name === 'product' && !project) || (route.name === 'delivery' && (!project || !stream)) || route.name === 'not-found') && <NotFound />}</main></div>
}

function Home(p: Row) {
    return <><Title over="LOCAL SYSTEM" title={p.system.status === 'ok' ? 'Ready to work' : 'Connecting…'} text={`${p.system.database ?? 'database'} · model router ${p.system.router?.status ?? 'unknown'}`} /><div className="metrics"><Metric n={p.count} label="Needs attention" hot={p.count > 0} /><Metric n={p.system.counts?.activeRuns ?? 0} label="Running" /><Metric n={p.scheduler.pendingOutbox ?? 0} label="Queued" /><Metric n={`${Math.round(p.resources.availableMiB ?? 0).toLocaleString()} MB`} label="Memory free" /></div><div className="dashboard"><Panel title="Needs attention">{p.count === 0 ? <Empty text="No workflow question, blocked run, artifact decision, or invalid artifact needs you." /> : <>{p.pendingDecisions.map((lc: Row) => <button className="row" key={lc.delivery.id} onClick={() => p.openStream(lc.delivery.id)}><Status value={lc.currentStage.state} /><span><b>{lc.recommendedAction?.label}</b><small>{lc.attention.label} · {lc.currentStage.label}</small></span></button>)}{p.attention.sessions?.map((x: Row) => <button className="row" key={x.id} onClick={() => p.openStream(x.workstreamId)}><Status value={x.status} /><span><b>{x.skill}</b><small>Workflow session</small></span></button>)}{p.attention.invalidArtifacts?.map((x: Row) => <button className="row" key={x.id} onClick={() => p.openStream(x.workstreamId)}><Status value="INVALID" /><span><b>{x.path}</b><small>Latest artifact revision is quarantined</small></span></button>)}</>}</Panel><Panel title="Active work" action={<button onClick={p.projects}>Start work</button>}>{p.streams.length ? <div className="cards">{p.streams.map((x: Row) => <DeliveryCard key={x.id} stream={x} lifecycle={p.deliveryStates[x.id]} open={p.openStream} />)}</div> : <Empty text="Create a project, attach a Git repository, and describe the work." />}</Panel></div></>
}

function DeliveryCard({ stream, lifecycle, open }: Row) { return <button className="card deliveryCard" onClick={() => open(stream.id)}><Status value={lifecycle?.currentStage?.state ?? stream.status} /><h3>{stream.title}</h3><p><strong>{lifecycle?.currentStage?.label ?? paths[stream.path]?.[0] ?? 'Path undecided'}</strong></p>{lifecycle?.attention && <small>Needs: {lifecycle.attention.label.split('/').at(-1)}</small>}{lifecycle?.recommendedAction && <span className="nextAction">Next: {lifecycle.recommendedAction.label}</span>}</button> }

function Products(p: Row) {
    const [query, setQuery] = useState(''), [creating, setCreating] = useState(false);
    const visible = p.portfolio.filter((entry: Row) => `${entry.product.name} ${entry.product.purpose} ${entry.activeGoal?.statement ?? ''}`.toLowerCase().includes(query.toLowerCase()));
    return <><Title over="PRODUCT PORTFOLIO" title="Products" text="Choose an enduring Product to see its direction, current commitment, and next decision." /><div className="portfolioTools"><Label text="Find a Product"><input type="search" value={query} onChange={e => setQuery(e.target.value)} placeholder="Search by name, purpose, or goal" /></Label><button onClick={() => setCreating(true)}>New Product</button></div>{creating && <Panel title="Create a Product" action={<button className="secondary" onClick={() => setCreating(false)}>Close</button>}><form className="productCreate" onSubmit={p.submit(async (d: Row) => { const product = await post('/products', { name: d.name, purpose: d.purpose, productGoal: d.productGoal }); navigate(productPath(product.slug)) })}><Label text="Product name"><input name="name" required autoFocus placeholder="Research Library" /></Label><Label text="Purpose"><textarea name="purpose" required placeholder="Who this Product helps and why it exists" /></Label><Label text="Proposed Product Goal"><textarea name="productGoal" required placeholder="The single valuable outcome the Product is working towards" /></Label><button>Create Product</button></form></Panel>}<Panel title="Your Products">{visible.length ? <div className="productCards">{visible.map((entry: Row) => <button className="card productCard" key={entry.product.id} onClick={() => p.open(entry.product.id)}><div className="head"><Status value={entry.attentionCount ? 'needs-attention' : entry.product.status} />{entry.currentSprint && <small>SPRINT {entry.currentSprint.number}</small>}</div><h3>{entry.product.name}</h3><p>{entry.product.purpose || 'Purpose has not been recorded yet.'}</p><div className="cardGoal"><small>PRODUCT GOAL</small><span>{entry.activeGoal?.statement ?? 'No active Product Goal'}</span></div><div className="productSignals"><span><b>{entry.activeDeliveryCount}</b> active deliveries</span><span><b>{entry.attentionCount}</b> need attention</span><span><b>{entry.repositoryCount}</b> repositories</span></div><span className="nextAction">{entry.nextAction ? `Next: ${entry.nextAction.label}` : 'No decision is waiting'}</span></button>)}</div> : <Empty text={query ? 'No Product matches this search.' : 'Create your first Product to establish its purpose and Product Goal.'} />}</Panel></>
}

function Project(p: Row) {
    const [health, setHealth] = useState<Record<string, Row>>({}), [detail, setDetail] = useState<Row>({ goals: [], features: [] }), [backlog, setBacklog] = useState<Row[]>([]), [sprints, setSprints] = useState<Row[]>([]), [increments, setIncrements] = useState<Row[]>([]);
    const loadProduct = async () => { const [d, b, s, i] = await Promise.all([api(`/products/${p.project.slug}`), api(`/product-backlog?projectId=${p.project.id}`), api(`/scrum-sprints?projectId=${p.project.id}`), api(`/increments?projectId=${p.project.id}`)]); setDetail(d); setBacklog(b); setSprints(s); setIncrements(i) };
    useEffect(() => { void loadProduct() }, [p.project.id]);
    const inspect = (repo: Row) => p.act('Refreshing repository capability catalog', async () => { await post(`/repositories/${repo.id}/bmad/refresh`); const [bmad, git] = await Promise.all([api(`/repositories/${repo.id}/bmad/health`), api(`/repositories/${repo.id}/git-health`)]); setHealth(x => ({ ...x, [repo.id]: { ...bmad, git } })) });
    const productBase = productPath(p.project.slug);
    const activeGoal = detail.goals?.find((x: Row) => x.status === 'active');
    return <><Title over="PRODUCT" title={p.project.name} text={activeGoal?.statement ?? 'Set the current Product Goal to give delivery decisions a shared direction.'} /><nav className="productTabs"><button className={p.section === 'overview' ? 'selected' : ''} onClick={() => navigate(productBase)}>Overview</button><button className={p.section === 'backlog' ? 'selected' : ''} onClick={() => navigate(`${productBase}/backlog`)}>Backlog and Sprints</button></nav>{p.section === 'overview' ? <>
      <div className="productGrid"><Panel title="Product Goal">{activeGoal ? <><Status value="active" /><p className="lead">{activeGoal.statement}</p></> : <Empty text="No active Product Goal." />}<details><summary>Propose or replace goal</summary><form onSubmit={p.submit(async (d: Row, f: HTMLFormElement) => { await post(`/products/${p.project.id}/goals`, { statement: d.statement, status: 'active' }); f.reset(); await loadProduct() })}><Label text="Goal statement"><textarea name="statement" required /></Label><button>Make active goal</button></form></details></Panel><Panel title="Definition of Done"><p>{detail.product?.definitionOfDone}</p><details><summary>Update Definition of Done</summary><form onSubmit={p.submit(async (d: Row) => { await post(`/products/${p.project.id}/definition-of-done`, { definitionOfDone: d.definitionOfDone }); await loadProduct() })}><Label text="Product-wide quality commitment"><textarea name="definitionOfDone" defaultValue={detail.product?.definitionOfDone} required /></Label><button>Save</button></form></details></Panel></div>
      <Panel title="Features" action={<details><summary>Add feature</summary><form className="popoverForm" onSubmit={p.submit(async (d: Row, f: HTMLFormElement) => { await post(`/products/${p.project.id}/features`, { name: d.name, description: d.description }); f.reset(); await loadProduct() })}><Label text="Feature"><input name="name" required /></Label><Label text="Description"><textarea name="description" /></Label><button>Add feature</button></form></details>}>{detail.features?.length ? <div className="cards">{detail.features.map((x: Row) => <article className="card" key={x.id}><Status value={x.status} /><h3>{x.name}</h3><p>{x.description}</p></article>)}</div> : <Empty text="No persistent product features recorded." />}</Panel>
      <div className="projectGrid"><Panel title="Repositories">{p.repos.map((repo: Row) => <article className="repo" key={repo.id}><b>{repo.path}</b><code>{repo.baseBranch} · {repo.role}</code><button className="secondary" onClick={() => void inspect(repo)}>Inspect capabilities</button>{health[repo.id] && <div className="health"><Status value={health[repo.id].healthy ? 'READY' : 'MISSING'} /><span>{health[repo.id].git?.clean ? 'Clean' : 'Changes present'} · {health[repo.id].git?.branch ?? 'unknown branch'} · {health[repo.id].definitions} operations</span></div>}</article>)}<details><summary>Attach repository</summary><form onSubmit={p.submit(async (d: Row, f: HTMLFormElement) => { await post(`/projects/${p.project.id}/repositories`, { path: d.path, baseBranch: d.baseBranch || 'main' }); f.reset() })}><Label text="Absolute Git path"><input name="path" required /></Label><Label text="Base branch"><input name="baseBranch" placeholder="main" /></Label><button>Attach</button></form></details></Panel><Panel title="Start delivery">{!p.repos.length ? <Empty text="Attach a repository first." /> : <form onSubmit={p.submit(async (d: Row, f: HTMLFormElement) => { const x = await post('/workstreams', { projectId: p.project.id, repositoryId: d.repositoryId, title: d.title, intent: d.intent, path: d.path }); f.reset(); p.open(x.id) })}><Label text="Repository"><select name="repositoryId">{p.repos.map((x: Row) => <option key={x.id} value={x.id}>{x.path}</option>)}</select></Label><Label text="Title"><input name="title" required /></Label><Label text="Brief"><textarea name="intent" required /></Label><fieldset><legend>Delivery approach</legend>{Object.entries(paths).map(([key, value]) => <label className="path" key={key}><input type="radio" name="path" value={key} required /><span><b>{value[0]}</b><em>{value[1]}</em></span></label>)}</fieldset><button>Create delivery</button></form>}</Panel></div><Panel title="Active deliveries">{p.streams.length ? <div className="cards">{p.streams.map((x: Row) => <DeliveryCard key={x.id} stream={x} lifecycle={p.deliveryStates[x.id]} open={p.open} />)}</div> : <Empty text="No delivery has started." />}</Panel>
    </> : <BacklogWorkspace {...p} detail={detail} backlog={backlog} sprints={sprints} increments={increments} reload={loadProduct} />}</>;
}

function BacklogWorkspace(p: Row) {
    const available = p.backlog.filter((x: Row) => x.item.status !== 'removed');
    return <div className="backlogLayout"><section><Panel title="Ordered Product Backlog"><form className="inlineCreate" onSubmit={p.submit(async (d: Row, f: HTMLFormElement) => { await post('/product-backlog', { projectId: p.project.id, featureId: d.featureId || undefined, kind: d.kind, title: d.title, description: d.description, acceptanceCriteria: d.acceptance ? d.acceptance.split('\n').filter(Boolean) : [] }); f.reset(); await p.reload() })}><Label text="Type"><select name="kind"><option>change</option><option>epic</option><option>story</option><option>defect</option><option>research</option><option>correction</option></select></Label><Label text="Title"><input name="title" required /></Label><Label text="Feature"><select name="featureId"><option value="">No feature</option>{p.detail.features?.map((x: Row) => <option key={x.id} value={x.id}>{x.name}</option>)}</select></Label><Label text="Description"><textarea name="description" /></Label><Label text="Acceptance criteria, one per line"><textarea name="acceptance" /></Label><button>Add backlog item</button></form>{available.length ? <div className="backlogList">{available.map((row: Row, index: number) => <article className="backlogItem" key={row.item.id}><span className="backlogOrder">{index + 1}</span><div><small>{row.item.kind}{row.feature ? ` · ${row.feature.name}` : ''}</small><h3>{row.item.title}</h3><p>{row.item.description}</p>{row.item.acceptanceCriteria?.map((x: string) => <span className="criterion" key={x}>✓ {x}</span>)}</div><select aria-label={`Status for ${row.item.title}`} value={row.item.status} onChange={e => void p.act('Updating backlog', async () => { await post(`/product-backlog/${row.item.id}/status`, { status: e.target.value }); await p.reload() })}><option>proposed</option><option>ready</option><option>in-progress</option><option>done</option><option>removed</option></select></article>)}</div> : <Empty text="The Product Backlog is empty." />}</Panel></section><aside><Panel title="Scrum Sprints"><form onSubmit={p.submit(async (d: Row, f: HTMLFormElement) => { await post('/scrum-sprints', { projectId: p.project.id, number: Number(d.number), goal: d.goal, startsAt: new Date(d.startsAt).toISOString(), endsAt: new Date(d.endsAt).toISOString() }); f.reset(); await p.reload() })}><Label text="Sprint number"><input name="number" type="number" min="1" required /></Label><Label text="Sprint Goal"><textarea name="goal" required /></Label><Label text="Starts"><input name="startsAt" type="datetime-local" required /></Label><Label text="Ends, no more than one month later"><input name="endsAt" type="datetime-local" required /></Label><button>Plan Sprint</button></form>{p.sprints.map((sprint: Row) => <article className="sprintCard" key={sprint.id}><Status value={sprint.status} /><small>SPRINT {sprint.number}</small><h3>{sprint.goal}</h3><p>{new Date(sprint.startsAt).toLocaleDateString()} – {new Date(sprint.endsAt).toLocaleDateString()}</p>{sprint.items.map((x: Row) => <span className="selectedPbi" key={x.id}>{x.title} · {x.status}</span>)}{sprint.status === 'planned' && <><Label text="Select ready backlog item"><select defaultValue="" onChange={e => { const value=e.target.value; if (value) void p.act('Selecting Sprint work', async () => { await post(`/scrum-sprints/${sprint.id}/items`, { backlogItemId: value }); await p.reload() }) }}><option value="">Choose item</option>{available.filter((x: Row) => x.item.status === 'ready' && !sprint.items.some((i: Row) => i.id === x.item.id)).map((x: Row) => <option value={x.item.id} key={x.item.id}>{x.item.title}</option>)}</select></Label><button onClick={() => void p.act('Starting Sprint', async () => { await post(`/scrum-sprints/${sprint.id}/status`, { status: 'active' }); await p.reload() })}>Start Sprint</button></>}</article>)}</Panel><Panel title="Usable Increments"><form onSubmit={p.submit(async (d: Row, f: HTMLFormElement) => { await post('/increments', { projectId: p.project.id, sprintId: d.sprintId || undefined, title: d.title, description: d.description, evidence: { recordedBy: 'Michael' } }); f.reset(); await p.reload() })}><Label text="Completed Sprint"><select name="sprintId"><option value="">Outside a Sprint</option>{p.sprints.filter((x: Row) => x.items.length > 0 && x.items.every((item: Row) => item.status === 'done')).map((x: Row) => <option key={x.id} value={x.id}>Sprint {x.number}</option>)}</select></Label><Label text="Increment"><input name="title" required /></Label><Label text="What is usable now?"><textarea name="description" /></Label><button>Record Increment</button></form>{p.increments.length ? p.increments.map((x: Row) => <article className="increment" key={x.id}><b>{x.title}</b><p>{x.description}</p><small>Definition of Done: {x.definitionOfDone}</small></article>) : <Empty text="No Increment has been recorded yet." />}</Panel></aside></div>;
}

function Workstream(p: Row) {
    const [navOpen, setNavOpen] = useState(false);
    const ops = Array.from(new Map(p.operations.map((x: Row) => [`${x.skill}:${x.action ?? ''}`, x])).values()) as Row[];
    const current = p.sessions.find((x: Row) => ['RUNNING', 'QUEUED', 'RESOURCE_WAITING', 'WAITING_FOR_INPUT', 'BLOCKED', 'NEEDS_CLASSIFICATION'].includes(x.status)) ?? p.sessions[0];
    const choosePath = p.stream.path === 'undecided' ? <section className="pathChoice"><h2>Choose the development path</h2><p>Read BMAD’s recommendation in the activity transcript, then select the path that will control the available operations.</p><div className="cards">{Object.entries(paths).filter(([key]) => key !== 'undecided').map(([key, value]) => <button className="card" key={key} onClick={() => void p.act('Selecting path', async () => { await post(`/workstreams/${p.stream.id}/path`, { path: key, actor: 'Michael' }); await p.load() })}><b>{value[0]}</b><p>{value[1]}</p><code>{value[2]}</code></button>)}</div></section> : null;
    return <><button className="back" onClick={p.back}>← Product</button><Title over={paths[p.stream.path]?.[0] ?? 'DELIVERY'} title={p.stream.title} text={deliverySummary(p.stream)} /><Journey lifecycle={p.lifecycle} /><div className="workspace"><code>{p.stream.branch ?? 'Workspace created on first workflow'}</code><code>{p.stream.workspacePath ?? ''}</code></div>{choosePath}<button className="mobileNavButton secondary" aria-expanded={navOpen} onClick={() => setNavOpen(x => !x)}>Browse activity and artifacts</button><div className="workGrid"><aside className={`panel rail ${navOpen ? 'open' : ''}`}><button className="mobileNavClose secondary" onClick={() => setNavOpen(false)}>Close navigation</button><h2>Activity</h2>{p.sessions.map((x: Row) => <button className={p.selectedSession?.id === x.id ? 'selected' : ''} key={x.id} onClick={() => { p.selectSession(x); setNavOpen(false) }}><Status value={x.status} /><span><b>{sessionTitle(x)}</b><small>{new Date(x.createdAt).toLocaleString()}</small></span></button>)}<h2>Artifacts</h2><button className="secondary" onClick={() => void p.act('Indexing', async () => { await post(`/workstreams/${p.stream.id}/artifacts/index`); await p.load() })}>Refresh index</button><ArtifactNavigation artifacts={p.artifacts} selected={p.selectedArtifact} choose={(x: Row) => { p.selectArtifact(x); setNavOpen(false) }} /><h2>Stories</h2><button className="secondary" onClick={() => void p.act('Reading stories', async () => { await post(`/workstreams/${p.stream.id}/stories/sync`); await p.load() })}>Read stories.yaml</button>{p.stories.map((x: Row) => <div className="story" key={x.id}><Status value={x.status} /><b>{x.storyKey}. {x.title}</b><small>{x.description}</small>{x.metadata?.repositoryRevision && <code>{x.metadata.repositoryRevision}</code>}<div><button disabled={!['backlog', 'ready-for-dev', 'blocked'].includes(x.status)} onClick={() => void p.act('Starting attended Build', async () => { await post(`/stories/${x.id}/dispatch`, { skill: 'bmad-build', actor: 'Michael' }); await p.load() })}>Build</button><button disabled={!['backlog', 'ready-for-dev', 'blocked'].includes(x.status)} className="secondary" onClick={() => void p.act('Starting Build Auto', async () => { await post(`/stories/${x.id}/dispatch`, { skill: 'bmad-build-auto', actor: 'Michael' }); await p.load() })}>Build Auto</button></div></div>)}{p.readiness.total > 0 && <div className="closure"><Status value={p.readiness.ready ? 'READY' : 'INCOMPLETE'} /><b>{p.readiness.total - p.readiness.unfinished.length}/{p.readiness.total} stories complete</b>{p.readiness.unfinished.map((x: Row) => <small key={x.id}>{x.id}: {x.status}</small>)}<button disabled={!p.readiness.ready} className="danger" onClick={() => void p.act('Integrating workstream', () => post(`/workstreams/${p.stream.id}/integrate`, { actor: 'Michael', confirm: true }))}>Fast-forward after final acceptance</button></div>}</aside><section className="panel stage" tabIndex={-1}>{p.selectedSession ? <Session session={p.selectedSession} artifacts={p.artifacts} openArtifact={p.selectArtifact} tab={p.route.tab ?? 'conversation'} changeTab={(tab: string) => navigate(`${deliveryPath(p.product.slug, p.stream.slug)}/runs/${p.selectedSession.id}?tab=${tab}`)} submit={p.submit} act={p.act} reload={() => p.selectSession(p.selectedSession)} /> : p.selectedArtifact ? <Artifact artifact={p.selectedArtifact} revisions={p.artifacts.filter((x: Row) => x.path === p.selectedArtifact.path)} graph={p.graph} submit={p.submit} act={p.act} reload={p.load} started={p.started} backToCurrent={() => navigate(deliveryPath(p.product.slug, p.stream.slug))} /> : p.route.view === 'advanced' ? <Start stream={p.stream} operations={ops} submit={p.submit} started={async (x: Row) => { await p.load(); p.started(x) }} /> : <CurrentTask {...p} />}</section></div></>;
}

function Start(p: Row) { const [id, setId] = useState(''), op = p.operations.find((x: Row) => x.id === id); return <><small>NEXT OPERATION</small><h2>Start a BMAD workflow</h2><p>Each operation opens one durable session. Interactive workflows stop here when they need your answer.</p>{!p.operations.length ? <Empty text="Inspect this repository’s BMAD installation from the Project page." /> : <form onSubmit={p.submit(async (d: Row) => p.started(await post('/workflow-sessions', { workstreamId: p.stream.id, skill: op.skill, action: op.action || undefined, prompt: d.prompt, args: {} })))}><Label text="Concrete operation"><select required value={id} onChange={e => setId(e.target.value)}><option value="">Choose an installed workflow</option>{p.operations.map((x: Row) => <option key={x.id} value={x.id}>{x.displayName} — {x.skill}{x.action ? `:${x.action}` : ''}</option>)}</select></Label>{op && <div className="operation"><b>{op.displayName}</b><p>{op.metadata?.description}</p><code>{op.skill}{op.action ? `:${op.action}` : ''}</code></div>}<Label text="Instructions"><textarea name="prompt" defaultValue={p.stream.intent} required /></Label><button disabled={!op}>Start {op?.skill ?? 'workflow'}</button></form>}</> }

function Journey({ lifecycle }: { lifecycle?: Row }) {
    if (!lifecycle) return <section className="journey"><div><small>CURRENT STAGE</small><h2>Loading delivery state…</h2></div></section>;
    return <section className="journey"><div><small>CURRENT STAGE</small><h2>{lifecycle.currentStage?.label}</h2><p>{lifecycle.reason}</p></div><div className="journeySteps">{lifecycle.stages?.map((stage: Row, index: number) => <span key={stage.id} className={stage.state === 'complete' ? 'done' : stage.id === lifecycle.currentStage?.id ? 'now' : ''}>{index + 1} {stage.label}</span>)}</div></section>;
}

function CurrentTask(p: Row) {
    const lc = p.lifecycle;
    const recommended = lc?.recommendedAction;
    useEffect(() => { if (recommended?.id) recordUx('recommended_action_shown', { workstreamId: p.stream.id, stage: lc?.currentStage?.id, action: recommended.id }) }, [p.stream.id, lc?.currentStage?.id, recommended?.id]);
    if (!lc) return <Empty text="Loading the current delivery decision…" />;
    const perform = async (candidate: Row) => {
        await post(`/workstreams/${p.stream.id}/actions/${candidate.id}/validate`, { actionToken: lc.actionToken });
        if (candidate.id === 'review-artifact' && lc.attention?.id) return p.selectArtifact(p.artifacts.find((x: Row) => x.id === lc.attention.id));
        if (['open-session', 'resume-session'].includes(candidate.id) && lc.attention?.id) {
            if (candidate.id === 'resume-session') await post(`/workflow-sessions/${lc.attention.id}/resume`, { actor: 'Michael' });
            return p.selectSession(p.sessions.find((x: Row) => x.id === lc.attention.id) ?? { id: lc.attention.id });
        }
        if (candidate.id === 'index-stories') { await post(`/workstreams/${p.stream.id}/stories/sync`); return p.load(); }
        if (candidate.id === 'deliver-story') return document.querySelector<HTMLElement>('.story')?.focus();
        if (candidate.operation?.skill) {
            const session = await post('/workflow-sessions', { workstreamId: p.stream.id, skill: candidate.operation.skill, action: candidate.operation.action, prompt: p.stream.intent, args: {} });
            await p.load(); return p.started(session);
        }
        if (candidate.id === 'advanced-actions') { recordUx('override_used', { workstreamId: p.stream.id, stage: lc.currentStage?.id }); return navigate(`${deliveryPath(p.product.slug, p.stream.slug)}/advanced`); }
    };
    return <div className="currentTask"><small>CURRENT TASK</small><h2>{lc.currentStage?.label}</h2><p className="currentReason">{lc.reason}</p><div className="ownershipStrip"><span><b>BMAD</b> plans, builds, and produces technical review evidence</span><span><b>MIC</b> preserves state and enforces your exact-revision approvals</span></div>{lc.attention && <div className="attentionTarget"><small>NEEDS ATTENTION</small><b>{lc.attention.label}</b><Status value={lc.attention.status ?? lc.currentStage.state} /></div>}{recommended && <section className="primaryAction"><small>RECOMMENDED NEXT ACTION</small><h3>{recommended.label}</h3><p>{recommended.description}</p><p><strong>After this:</strong> {lc.stages?.find((x: Row) => x.id === recommended.transition)?.label ?? recommended.transition}</p><button disabled={!recommended.eligible} onClick={() => void p.act(recommended.label, () => perform(recommended))}>{recommended.label}</button>{recommended.reason && <small>{recommended.reason}</small>}</section>}<details className="briefDisclosure"><summary>Original Brief</summary><div className="document"><Markdown source={lc.delivery.brief} /></div></details><details className="advancedDisclosure"><summary>Advanced actions</summary>{lc.alternativeActions?.map((candidate: Row) => <div className="alternativeAction" key={candidate.id}><div><b>{candidate.label}</b><p>{candidate.description}</p>{!candidate.eligible && <small>{candidate.reason}</small>}</div><button className="secondary" disabled={!candidate.eligible} onClick={() => void p.act(candidate.label, () => perform(candidate))}>Open</button></div>)}</details></div>;
}

function sessionTitle(session: Row) {
    const purpose = session.skill === 'bmad-spec' && session.action === 'create-stories' ? 'Story Breakdown' : session.skill === 'bmad-spec' ? 'Specification' : session.skill === 'bmad-build' ? 'Attended Build' : session.skill === 'bmad-build-auto' ? 'Build Auto' : session.skill.replace(/^bmad-/, '').replaceAll('-', ' ');
    const result = session.status === 'FINISHED' ? 'complete' : session.status === 'WAITING_FOR_INPUT' ? 'awaiting your answer' : session.status.toLowerCase().replaceAll('_', ' ');
    return `${purpose} — ${result}`;
}

function Session(p: Row) {
    const s = p.session, active = ['RUNNING', 'QUEUED', 'RESOURCE_WAITING'].includes(s.status), waiting = ['WAITING_FOR_INPUT', 'BLOCKED'].includes(s.status);
    const transcriptRef = React.useRef<HTMLDivElement>(null);
    useEffect(() => { const node = transcriptRef.current; if (node) node.scrollTop = node.scrollHeight }, [s.turns?.length]);
    const state = active ? { title: 'Work is in progress', reason: 'No feedback is expected while this operation runs.', next: 'When it finishes, MIC will show its output or a specific question.' }
      : waiting ? { title: 'Your decision is required', reason: s.status === 'BLOCKED' ? 'The workflow cannot safely continue without this answer.' : 'The workflow deliberately stopped at an interactive checkpoint.', next: 'Your response is added to this same durable session, then execution continues from its checkpoint.' }
      : s.status === 'NEEDS_CLASSIFICATION' ? { title: 'MIC cannot prove the outcome', reason: 'The process exited without a changed terminal artifact or a clear human question.', next: 'Classify the response from the evidence below; classification does not approve an artifact.' }
      : s.status === 'PAUSED' ? { title: 'Paused at a checkpoint', reason: 'The provider session and worktree remain available.', next: 'Resume continues this operation from its preserved checkpoint.' }
      : s.status === 'INTERRUPTED' ? { title: 'Execution was interrupted', reason: 'MIC restarted while this operation was active.', next: 'Resume reconnects to the durable provider session and existing worktree.' }
      : { title: 'This operation is complete', reason: 'This session is retained as delivery history.', next: 'Open its output or return to the current guided task.' };
    const placeholder = s.skill === 'bmad-spec' ? 'State the exact requirement that is wrong or missing, and the result you need in the next revision…' : 'Answer the concrete question above in plain language…';
    const tabs = ['conversation', 'outputs', 'logs', 'details'];
    const raw = s.rawState?.rawAdapterState ?? s.rawState ?? {};
    const outputs = p.artifacts.filter((x: Row) => x.sessionId === s.id);
    return <div className="chatShell"><div className="chatHeader"><div><small>WORKFLOW RUN</small><h2>{sessionTitle(s)}</h2><code>{s.skill}{s.action ? `:${s.action}` : ''}</code></div><Status value={s.status} /></div><nav className="runTabs" aria-label="Run details">{tabs.map(tab => <button className={p.tab === tab ? 'selected' : ''} key={tab} onClick={() => p.changeTab(tab)}>{tab}</button>)}</nav>{p.tab === 'conversation' && <><section className={`decisionGuide ${waiting || s.status === 'NEEDS_CLASSIFICATION' ? 'needs' : ''}`}><b>{state.title}</b><p><strong>Why:</strong> {state.reason}</p><p><strong>Next:</strong> {state.next}</p></section><div className="transcript" ref={transcriptRef} role="log" aria-live="polite">{(s.turns ?? []).map((x: Row) => <ChatMessage turn={x} key={x.id} />)}</div>{waiting && <form className="composer" onSubmit={p.submit(async (d: Row, f: HTMLFormElement) => { await post(`/workflow-sessions/${s.id}/respond`, { content: d.content, actor: 'Michael' }); f.reset(); await p.reload() })}><Label text="What MIC needs from you"><textarea name="content" required autoFocus placeholder={placeholder} /></Label><small>Say what you accept or reject, what must change, and any constraint that must be preserved.</small><button>Send decision and continue</button></form>}</>}{p.tab === 'outputs' && <section className="runPane"><h3>Outputs</h3>{outputs.length ? outputs.map((x: Row) => <button className="row" key={x.id} onClick={() => p.openArtifact(x)}><Status value={x.status ?? x.type} /><span><b>{x.path}</b><small>{x.contentHash.slice(0, 10)}</small></span></button>) : <Empty text="This run has no indexed artifact output yet." />}</section>}{p.tab === 'logs' && <section className="runPane"><h3>Execution logs</h3><pre>{[raw.stdout, raw.stderr].filter(Boolean).join('\n') || 'No captured process log is available for this workflow run.'}</pre></section>}{p.tab === 'details' && <section className="runPane"><h3>Run details</h3><dl><dt>Started</dt><dd>{new Date(s.createdAt).toLocaleString()}</dd><dt>Updated</dt><dd>{new Date(s.updatedAt).toLocaleString()}</dd><dt>Provider session</dt><dd><code>{s.providerSessionId ?? 'Not assigned'}</code></dd><dt>Operation</dt><dd><code>{s.skill}{s.action ? `:${s.action}` : ''}</code></dd></dl><details><summary>Raw execution state</summary><pre>{JSON.stringify(s.rawState, null, 2)}</pre></details></section>}{waiting && <button className="falseWait" onClick={() => void p.act('Correcting state', () => post(`/workflow-sessions/${s.id}/classify`, { classification: 'finished', actor: 'Michael' }))}>This response contains no question — mark operation finished</button>}{s.status === 'NEEDS_CLASSIFICATION' && <div className="classify"><b>Choose what the evidence means</b><p><strong>Waiting</strong> means the text contains a real request you must answer. <strong>Finished</strong> means the operation ended; it does not approve its output.</p><button onClick={() => void p.act('Classifying', () => post(`/workflow-sessions/${s.id}/classify`, { classification: 'waiting', actor: 'Michael' }))}>It contains a real question</button><button className="secondary" onClick={() => void p.act('Classifying', () => post(`/workflow-sessions/${s.id}/classify`, { classification: 'finished', actor: 'Michael' }))}>It finished without a question</button></div>}<div className="actions runRecovery">{active && <button className="secondary" onClick={() => void p.act('Pausing', () => post(`/workflow-sessions/${s.id}/pause`, { actor: 'Michael' }))}>Pause at checkpoint</button>}{active && <button className="danger" onClick={() => void p.act('Cancelling', () => post(`/workflow-sessions/${s.id}/cancel`, { actor: 'Michael' }))}>Cancel operation</button>}{['PAUSED', 'INTERRUPTED', 'FAILED'].includes(s.status) && <button onClick={() => void p.act('Resuming', () => post(`/workflow-sessions/${s.id}/resume`, { actor: 'Michael' }))}>Resume from checkpoint</button>}</div></div>;
}

function ChatMessage({ turn }: { turn: Row }) {
    const long = turn.content.length > 1800;
    return <article className={`message ${turn.role}`}><div className="avatar">{turn.role === 'user' ? 'M' : 'B'}</div><div className="messageBody"><small>{turn.role === 'user' ? 'YOU' : 'BMAD'}</small>{long && turn.role === 'user' ? <details><summary>Show full instruction ({turn.content.length.toLocaleString()} characters)</summary><Markdown source={turn.content} /></details> : <Markdown source={turn.content} />}</div></article>;
}

function ArtifactNavigation({ artifacts, selected, choose }: Row) {
    const latest = artifacts.filter((x: Row, index: number) => artifacts.findIndex((candidate: Row) => candidate.path === x.path) === index);
    const history = artifacts.filter((x: Row) => !latest.some((current: Row) => current.id === x.id));
    const group = (type: string) => type === 'spec' || type === 'prd' ? 'Current plan' : type === 'story-inventory' || type === 'sprint-status' ? 'Story plan' : type === 'architecture' ? 'Architecture and UX' : type === 'story' ? 'Implementation' : type === 'memlog' ? 'Decision history' : 'Evidence and supporting documents';
    const groups = new Map<string, Row[]>();
    for (const artifact of latest) { const name = group(artifact.type); groups.set(name, [...(groups.get(name) ?? []), artifact]); }
    const item = (x: Row, note: string) => <button className={selected?.id === x.id ? 'selected' : ''} key={x.id} onClick={() => choose(x)}><Status value={x.status ?? x.type} /><span><b>{x.path.split('/').at(-1)}</b><small>{note} · {x.contentHash.slice(0, 8)}</small></span></button>;
    return <div className="artifactNav">{[...groups].map(([name, values]) => <section key={name}><h3>{name}</h3>{values.map(x => item(x, 'Current'))}</section>)}{history.length > 0 && <details><summary>History ({history.length})</summary>{history.map((x: Row) => item(x, new Date(x.createdAt).toLocaleString()))}</details>}</div>;
}

function Artifact(p: Row) {
    const a = p.artifact, m = a.metadata ?? {}, [compare, setCompare] = useState(''), [diff, setDiff] = useState<Row>(), [reviews, setReviews] = useState<Row[]>([]), [focus, setFocus] = useState(false);
    const reviewOpened = React.useRef(performance.now());
    useEffect(() => { setCompare(''); setDiff(undefined); void api(`/artifacts/${a.id}/reviews`).then(setReviews) }, [a.id]);
    const incoming = p.graph.links?.filter((x: Row) => x.toArtifactId === a.id) ?? [], outgoing = p.graph.links?.filter((x: Row) => x.fromArtifactId === a.id) ?? [], byId = new Map((p.graph.nodes ?? []).map((x: Row) => [x.id, x]));
    const latest = p.revisions[0]?.id === a.id, reviewable = latest && m.valid !== false && a.status !== 'quarantined';
    const feedback = (data: Row) => [data.change && `Change: ${data.change}`, data.preserve && `Preserve: ${data.preserve}`, data.constraint && `Constraint: ${data.constraint}`].filter(Boolean).join('\n');
    const recordDecision = (decision: string) => recordUx('artifact_decision', { artifactId: a.id, decision, latencyMs: Math.round(performance.now() - reviewOpened.current) });
    return <div className={focus ? 'artifactWorkspace focus' : 'artifactWorkspace'}><div className="head"><div><small>{a.type}</small><h2>{a.path.split('/').at(-1)}</h2></div><div className="actions"><Status value={a.status ?? (m.valid ? 'VALID' : 'INVALID')} /><button className="secondary" onClick={() => setFocus(x => !x)}>{focus ? 'Exit focus' : 'Focus document'}</button></div></div>{m.issues?.length > 0 && <Notice kind="error" text={m.issues.join(' · ')} />}<section className="artifactDecision"><b>{reviewable ? 'Decide whether this exact revision is ready' : latest ? 'This revision cannot be accepted' : 'This is a previous revision'}</b><p>{reviewable ? 'Accept only if this document states the outcome, behavior, and constraints that should govern downstream work. Request changes when any consequential point is wrong or missing.' : latest ? 'Resolve the validation issue before acceptance.' : 'Open the artifact marked Current to make a decision.'}</p><p><strong>After acceptance:</strong> {a.type === 'spec' ? 'MIC immediately starts BMAD Story Breakdown. The resulting stories.yaml still requires your approval.' : a.type === 'story-inventory' ? 'MIC synchronizes these exact Stories into the Product Backlog.' : 'MIC advances the delivery to the next defined activity.'}</p><p><strong>Feedback owner:</strong> {a.sessionId ? 'the workflow that produced this document' : 'no owning workflow is recorded'}</p></section><div className="cues">{m.assumptions?.length > 0 && <Cue title="Assumptions" values={m.assumptions} />} {m.questions?.length > 0 && <Cue title="Open questions" values={m.questions} />} {m.conflicts?.length > 0 && <Cue title="Conflicts" values={m.conflicts} />}</div>{(incoming.length > 0 || outgoing.length > 0) && <div className="relations"><b>Artifact relationships</b>{incoming.map((x: Row) => <small key={x.id}>Uses {(byId.get(x.fromArtifactId) as Row)?.path}</small>)}{outgoing.map((x: Row) => <small key={x.id}>Source for {(byId.get(x.toArtifactId) as Row)?.path}</small>)}</div>}<div className="document"><Markdown source={a.content} /></div>{p.revisions.length > 1 && <div className="revision"><Label text="Compare this exact revision with"><select value={compare} onChange={e => setCompare(e.target.value)}><option value="">Choose revision</option>{p.revisions.filter((x: Row) => x.id !== a.id).map((x: Row) => <option value={x.id} key={x.id}>{new Date(x.createdAt).toLocaleString()} · {x.contentHash.slice(0, 10)}</option>)}</select></Label><button disabled={!compare} className="secondary" onClick={() => void p.act('Comparing revisions', async () => setDiff(await api(`/artifact-diff?from=${compare}&to=${a.id}`)))}>Show diff</button>{diff && <pre>{diff.changes.join('\n')}</pre>}</div>}<div className="reviewControls"><a className="button secondary" href={`/artifacts/${a.id}/download`}>Download source</a><button disabled={!reviewable} onClick={() => { recordDecision('accepted'); void p.act('Accepting revision', async () => { await post(`/artifacts/${a.id}/reviews`, { kind: 'accepted', actor: 'Michael' }); await p.reload(); p.backToCurrent() }) }}>Accept this revision</button></div>{reviews.length > 0 && <div className="reviewTrail"><b>Review trail for this revision</b>{reviews.map((x: Row) => <p key={x.id}><Status value={x.kind} /> {x.actor} · {new Date(x.createdAt).toLocaleString()}{x.feedback ? ` — ${x.feedback}` : ''}</p>)}</div>}<form className="feedbackForm" onSubmit={p.submit(async (d: Row, form: HTMLFormElement) => { recordDecision('changes_requested'); const result = await post(`/artifacts/${a.id}/feedback`, { feedback: feedback(d), actor: 'Michael' }); form.reset(); await p.reload(); p.started(result.session) })}><h3>Request changes</h3><Label text="What must change?"><textarea name="change" required placeholder="State the incorrect or missing outcome…" /></Label><Label text="What must remain?"><textarea name="preserve" placeholder="Record decisions or behavior the revision must preserve…" /></Label><Label text="What constraint must be respected?"><textarea name="constraint" placeholder="Name any boundary the next revision must not cross…" /></Label><small>Your feedback is recorded against this exact revision. MIC opens the owning workflow as a new revision conversation.</small><button className="secondary" disabled={!reviewable}>Send feedback and start revision</button></form><details className="provenance"><summary>Technical provenance</summary><code>{a.contentHash} · {a.repositoryRevision}</code></details></div>;
}

function Markdown({ source }: { source: string }) { return <div className="markdown">{source.split(/\r?\n/).map((line, i) => line.startsWith('# ') ? <h1 key={i}>{line.slice(2)}</h1> : line.startsWith('## ') ? <h2 key={i}>{line.slice(3)}</h2> : line.startsWith('### ') ? <h3 key={i}>{line.slice(4)}</h3> : /^[-*] /.test(line) ? <p className="bullet" key={i}>• {line.slice(2)}</p> : <p key={i}>{line || ' '}</p>)}</div> }
function Breadcrumbs({ items }: { items: Array<Array<string | undefined>> }) { return <nav className="breadcrumbs" aria-label="Breadcrumb">{items.map(([label, path], index) => <React.Fragment key={`${label}-${index}`}>{index > 0 && <span aria-hidden="true">/</span>}{path ? <button onClick={() => navigate(path)}>{label}</button> : <span aria-current="page">{label}</span>}</React.Fragment>)}</nav> }
function NotFound() { return <section className="panel notFound"><small>NOT FOUND</small><h1>This MIC location does not exist</h1><p>The product or delivery may have been renamed, or the link may be incomplete.</p><button onClick={() => navigate('/products')}>Open Products</button></section> }
function UxEvidencePanel() { const [events, setEvents] = useState(() => readUxEvidence()); return <><Title over="LOCAL DIAGNOSTICS" title="UX evidence" text="MIC keeps recent journey evidence in this browser only. It is never sent to an external telemetry service." /><Panel title="Recent journey events" action={<button className="secondary" onClick={() => { clearUxEvidence(); setEvents([]) }}>Clear evidence</button>}>{events.length ? <div className="evidenceList">{events.slice().reverse().map((entry, index) => <details key={`${entry.at}-${index}`}><summary>{entry.event.replaceAll('_', ' ')} · {new Date(entry.at).toLocaleString()}</summary><pre>{JSON.stringify(entry.detail, null, 2)}</pre></details>)}</div> : <Empty text="No local journey evidence has been recorded in this browser." />}</Panel></> }
function Problem({ problem, retry, dismiss }: { problem: Row; retry: () => void; dismiss: () => void }) { return <section className="notice error problem" role="alert"><div><b>{problem.message}</b><p>{problem.code === 'stale_or_ineligible_action' ? 'MIC refreshed the delivery state. Review the current action and try again.' : 'The requested action did not complete. Your entered text remains available where possible.'}</p></div><div className="actions"><button className="secondary" onClick={retry}>Refresh and retry</button><button className="secondary" onClick={dismiss}>Dismiss</button></div>{problem.code && <details><summary>Technical details</summary><code>{problem.status} · {problem.code}</code></details>}</section> }
function Panel({ title, action, children }: { title: string; action?: React.ReactNode; children: React.ReactNode }) { return <section className="panel"><div className="head"><h2>{title}</h2>{action}</div>{children}</section> } function Title({ over, title, text }: { over: string; title: string; text: string }) { return <section className="title"><small>{over}</small><h1>{title}</h1><p>{text}</p></section> } function Label({ text, children }: { text: string; children: React.ReactNode }) { return <label>{text}{children}</label> } function Status({ value }: { value: string }) { const label = String(value).replaceAll('_', ' '); return <span aria-label={`Status: ${label}`} className={`status ${String(value).toLowerCase().replaceAll('_', '-')}`}>{label}</span> } function Metric({ n, label, hot }: { n: any; label: string; hot?: boolean }) { return <div className={hot ? 'hot' : ''}><strong>{n}</strong><small>{label}</small></div> } function Empty({ text }: { text: string }) { return <div className="empty">{text}</div> } function Notice({ kind, text }: { kind: string; text: string }) { return <div className={`notice ${kind}`}>{text}</div> } function Cue({ title, values }: { title: string; values: string[] }) { return <div><b>{title}</b>{values.map((x, i) => <p key={i}>{x}</p>)}</div> }
createRoot(document.getElementById('root')!).render(<App />);
